script:
frappe.ui.form.on('Quotation', {
  refresh(frm) {
    if (frm.is_new()) return;
    const canJO = ['System Manager','Job Order Admin','Job Order Admin Support'].some(r => frappe.user.has_role(r));
    frm.clear_custom_buttons();
    // Create Job Order (auto-filled) — accepted proposal not yet converted
    if (canJO && frm.doc.custom_client_acceptance_confirmed && !frm.doc.custom_job_order_created) {
      const btn = frm.add_custom_button(__('Create Job Order'), () => {
        frappe.model.open_mapped_doc({ method: 'saif_erp.job_order.make_job_order', frm: frm });
      });
      btn.css({'background-color':'#28a745','border-color':'#28a745','color':'#ffffff'});
    }
    // Already converted → jump to the Job Order
    if (frm.doc.custom_job_order) {
      frm.add_custom_button(__('View Job Order'), () => frappe.set_route('Form','Job Order',frm.doc.custom_job_order));
    }
    // hide the default Create (Sales Order) / Set as Lost buttons
    const hide = () => {
      frm.page.page_actions.find('button, a').filter(function () {
        const t = $(this).text().trim();
        return t === __('Create') || t === __('Set as Lost');
      }).hide();
    };
    hide(); setTimeout(hide, 300); setTimeout(hide, 1000);
  }
});

frappe.ui.form.on('Job Order', {
  refresh(frm) {
    const can = frappe.user.has_role('Reviewer');
    ['custom_reviewer_rating','custom_review_remark'].forEach(f => frm.set_df_property(f,'read_only', can?0:1));
    if (!can) frm.set_df_property('custom_reviewer_rating','description','Only a Reviewer can set this mark.');
  }
});

frappe.ui.form.on('Job Order', {
  refresh: sga_render_progress,
  approval_status: sga_render_progress,
  job_status: sga_render_progress,
  custom_review_date: sga_render_progress,
  custom_reviewer_rating: sga_render_progress,
  draft_sent_date: sga_render_progress,
  draft_approved_date: sga_render_progress,
  report_printed: sga_render_progress,
  payment_status: sga_render_progress,
  report_delivery_status: sga_render_progress,
});

function sga_render_progress(frm) {
  if (frm.is_new()) return;
  const d = frm.doc;
  const audit = String(d.service || '').toLowerCase().indexOf('audit') !== -1;
  const steps = [
    ['Approved', d.approval_status === 'Approved'],
    ['Sent for review', d.job_status === 'Under Review' || !!d.custom_review_date],
    ['Reviewed', !!(d.custom_review_date || d.custom_reviewer_rating)],
    ['Draft sent to client', !!d.draft_sent_date],
    ['Draft approved by client', !!d.draft_approved_date],
  ];
  if (audit) steps.push(['Report printed', !!d.report_printed]);
  steps.push(['Payment received', d.payment_status === 'Paid']);
  steps.push(['Delivered', d.report_delivery_status === 'Yes' || !!d.report_delivery_date]);

  let furthest = -1;
  steps.forEach((s, i) => { if (s[1]) furthest = i; });
  const total = steps.length;
  const pct = furthest < 0 ? 0 : Math.round((furthest + 1) / total * 100);
  const stage = d.custom_stage || 'Pending approval';

  const chips = steps.map((s, i) => {
    const done = s[1], cur = (i === furthest + 1);
    const ic = done ? '<span style="color:#15803d">&#10003;</span>'
             : (cur ? '<span style="color:#b45309">&#9679;</span>'
                    : '<span style="color:#c3c9c6">&#9675;</span>');
    const col = done ? '#111827' : (cur ? '#b45309' : '#9aa2a0');
    const fw = (done || cur) ? 600 : 400;
    return '<span style="display:inline-block;margin:2px 18px 2px 0;color:' + col
         + ';font-weight:' + fw + ';font-size:12px;white-space:nowrap">' + ic + ' '
         + frappe.utils.escape_html(s[0]) + '</span>';
  }).join('');

  const html = '<div style="border:1px solid #e5e7eb;border-radius:8px;padding:12px 16px;background:#fbfdfc">'
    + '<div style="display:flex;justify-content:space-between;align-items:center;font-size:12px;font-weight:700">'
    + '<span style="letter-spacing:.4px;color:#6b7280">JOB PROGRESS</span>'
    + '<span style="color:#16794c">' + frappe.utils.escape_html(stage) + ' &middot; ' + pct + '%</span></div>'
    + '<div style="height:8px;background:#e9edeb;border-radius:99px;margin:8px 0 11px;overflow:hidden">'
    + '<div style="height:100%;width:' + pct + '%;background:linear-gradient(90deg,#0E4A34,#16794c)"></div></div>'
    + '<div>' + chips + '</div></div>';

  const $d = frm.dashboard.wrapper;
  $d.find('.sga-prog').remove();
  $d.prepend('<div class="sga-prog" style="padding:8px 0 2px">' + html + '</div>');
  frm.dashboard.show();
}
